fn tile(x: i32, y: i32, tw: i32, th: i32) {
    host::display::fill_rect(x, y, tw, th, 0x303038);
    host::display::fill_rect(x + 2, y + 2, tw - 4, th - 4, 0x14141a);
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    let mut taps: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 { taps = taps + 1; }
    host::display::state_set(0, taps);
    host::display::state_set(1, down);
    host::display::clear(0x000000);
    let tw: i32 = w / 2 - 12;
    let th: i32 = h / 2 - 12;
    tile(8, 8, tw, th);
    host::display::draw_string(20, 20, "UPTIME S", 0x808080, 1);
    host::display::draw_number(20, 40, t / 60, 0xffffff, 5);
    tile(w / 2 + 4, 8, tw, th);
    host::display::draw_string(w / 2 + 16, 20, "FRAMES", 0x808080, 1);
    host::display::draw_number(w / 2 + 16, 40, t, 0xffffff, 4);
    tile(8, h / 2 + 4, tw, th);
    host::display::draw_string(20, h / 2 + 16, "TAPS", 0x808080, 1);
    host::display::draw_number(20, h / 2 + 36, taps, 0xffffff, 5);
    tile(w / 2 + 4, h / 2 + 4, tw, th);
    host::display::draw_string(w / 2 + 16, h / 2 + 16, "TAPS PER MIN", 0x808080, 1);
    host::display::draw_number(w / 2 + 16, h / 2 + 36, taps * 3600 / (t + 1), 0xffffff, 5);
    host::display::present();
}
